9	/**
10	 * When the create request carries an email, requires it to be a syntactically valid address and
11	 * stores it lower-cased, mutating the published {@link OwnerFieldsDto} in place so {@link BuildOwner}
12	 * maps the normalised value. A missing email is left untouched; an invalid one is rejected with 400.
13	 */
14	public class NormalizeOwnerEmail {
15	
16	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerEmailException {
19	        String email = request.getEmail();
20	        if (email == null) {
21	            return;
22	        }
23	        if (!EMAIL.matcher(email).matches()) {
24	            throw new InvalidOwnerEmailException(email);
25	        }
26	        request.setEmail(email.toLowerCase());
27	    }
28	}
