1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When a create request opts in with {@code sharesHousehold=true}, assigns the new owner and every
10	 * existing same-lastName owner at the same address a stable shared {@code householdId}. The id is
11	 * derived deterministically from the normalised last name and address, so all members of one
12	 * household compute the same value. A request that does not opt in is left untouched.
13	 */
14	public class AssignHousehold {
15	
16	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
17	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
18	            return;
19	        }
20	        String lastName = normalize(owner.getLastName());
21	        String address = normalize(owner.getAddress());
22	        String householdId = String.format("HH-%08X", (lastName + "|" + address).hashCode());
23	        owner.setHouseholdId(householdId);
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (lastName.equals(normalize(existing.getLastName()))
26	                    && address.equals(normalize(existing.getAddress()))) {
27	                existing.setHouseholdId(householdId);
28	                ownerRepository.save(existing);
29	            }
30	        }
31	    }
32	
33	    private static String normalize(String value) {
34	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
35	    }
36	}
